# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: gather
def gather(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: digest
def digest(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(gather(emit(fold(raw))))

